import test from "node:test";
import assert from "node:assert/strict";
import { page } from "../src/pagination.ts";
import { DocumentService } from "../src/service.ts";

test("pagination traverses every ID once without mutating input", () => {
  const records = Object.freeze(["z", "a", "Z", "", "A", "é", "10", "2"]
    .map(id => Object.freeze({ id, body: { title: id } })));
  const before = structuredClone(records);
  const expected = records.map(record => record.id).sort();
  for (const limit of [1, 2, 3, 8, 100]) {
    const seen = [];
    let cursor;
    for (let count = 0; count <= records.length; count++) {
      const result = page(records, { cursor, limit });
      seen.push(...result.items.map(record => record.id));
      if (result.next_cursor === null) break;
      assert.equal(result.next_cursor, result.items.at(-1).id);
      cursor = result.next_cursor;
    }
    assert.deepEqual(seen, expected);
  }
  assert.deepEqual(records, before);
});

test("cursor boundaries and final pages", () => {
  const records = [{ id: "a" }, { id: "c" }, { id: "e" }];
  assert.deepEqual(page(records, { cursor: "b", limit: 1 }), {
    items: [{ id: "c" }], next_cursor: "c",
  });
  assert.deepEqual(page(records, { cursor: "c", limit: 1 }), {
    items: [{ id: "e" }], next_cursor: null,
  });
  assert.deepEqual(page(records, { cursor: "z" }), { items: [], next_cursor: null });
  assert.deepEqual(page([]), { items: [], next_cursor: null });
});

test("limit validation and defaults are preserved", () => {
  for (const limit of [0, -1, 101, 1.5, NaN, Infinity]) {
    assert.throws(() => page([], { limit }), /limit must be between 1 and 100/);
  }
  const records = Array.from({ length: 21 }, (_, i) => ({ id: String(i).padStart(2, "0") }));
  assert.equal(page(records).items.length, 20);
  assert.equal(page(records).next_cursor, "19");
});

test("DocumentService traverses pages and resumes after deleting the cursor", () => {
  for (const deleteCursor of [false, true]) {
    const service = new DocumentService();
    const ids = ["d", "a", "C", "b", "A"];
    for (const id of ids) service.repository.create(id, { title: id });
    const seen = [];
    let cursor;
    for (let count = 0; count <= ids.length; count++) {
      const result = service.listDocuments(cursor, 2);
      seen.push(...result.items.map(record => record.id));
      if (result.next_cursor === null) break;
      cursor = result.next_cursor;
      if (deleteCursor) service.repository.records.delete(cursor);
    }
    assert.deepEqual(seen, [...ids].sort());
    assert.deepEqual(service.listDocuments("z", 2), { items: [], next_cursor: null });
    assert.throws(() => service.listDocuments(undefined, 0), /limit must be between 1 and 100/);
  }
});

export type Identified = { id: string };
export function page<T extends Identified>(
  records: T[], options: { cursor?: string; limit?: number } = {},
): { items: T[]; next_cursor: string | null } {
  const limit = options.limit ?? 20;
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    throw new Error("limit must be between 1 and 100");
  }
  // Use the same ID ordering for sorting and the exclusive cursor boundary.
  let ordered = [...records].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  if (options.cursor !== undefined) {
    ordered = ordered.filter(item => item.id > options.cursor!);
  }
  const selected = ordered.slice(0, limit);
  return { items: selected,
    next_cursor: ordered.length > limit ? selected.at(-1)!.id : null };
}

